class EventScheduler:
    def __init__(self, components):
        self.components = components

    def run(self, stop_time: float) -> float:
        now = 0.0
        while now < stop_time:
            next_times = [component.next_event_time(now)
                          for component in self.components]
            target = min([stop_time, *next_times])
            if target <= now:
                raise RuntimeError('components must report a future event')

            for component in self.components:
                component.advance_to(target)
            for component in self.components:
                component.process_events_at(target)
            now = target

        return now
